package solution

import (
	"sync"
)

// ParallelMap applies f to every element of in using at most workers
// goroutines and returns the results in the same order as the input.
//
// If workers <= 0, one worker is used per element. An empty input yields
// an empty (non-nil) result. Each output slot is written by exactly one
// goroutine, so the operation is data-race-free.
func ParallelMap[T, R any](in []T, workers int, f func(T) R) []R {
	if len(in) == 0 {
		return make([]R, 0)
	}

	if workers <= 0 {
		workers = len(in)
	}

	var wg sync.WaitGroup
	out := make([]R, len(in))

	for i, chunkSize := range chunkSizes(len(in), workers) {
		wg.Add(1)
		go func(i, start int, size int) {
			defer wg.Done()
			for j := 0; j < size; j++ {
				out[start+j] = f(in[start+j])
			}
		}(i, chunkStart(i, len(in), workers), chunkSize)
	}

	wg.Wait()
	return out
}

func chunkSizes(n, k int) []int {
	sizes := make([]int, k)
	baseSize := n / k
	remainder := n % k
	for i := 0; i < k; i++ {
		sizes[i] = baseSize
		if i < remainder {
			sizes[i]++
		}
	}
	return sizes
}

func chunkStart(i, n, k int) int {
	sizes := chunkSizes(n, k)
	start := 0
	for j := 0; j < i; j++ {
		start += sizes[j]
	}
	return start
}

