var ErrNoFuncs = errors.New("no functions provided")

func FirstSuccess(ctx context.Context, fns []func(context.Context) (int, error)) (int, error) {
	if len(fns) == 0 {
		return 0, ErrNoFuncs
	}

	ctx, cancel := context.WithCancel(ctx)
	defer cancel()

	var (
		wg     sync.WaitGroup
		result int
		err    error
		mu     sync.Mutex
		done   bool
	)

	for _, fn := range fns {
		wg.Add(1)
		go func(fn func(context.Context) (int, error)) {
			defer wg.Done()
			r, e := fn(ctx)
			mu.Lock()
			defer mu.Unlock()
			if !done {
				if e == nil {
					result = r
					done = true
					cancel()
				} else {
					err = e
				}
			}
		}(fn)
	}

	wg.Wait()
	mu.Lock()
	defer mu.Unlock()
	if done {
		return result, nil
	}
	return 0, err
}

