import (
	"sync"
)

// ParallelHistogram counts how many times each value appears in nums, sharding
// the work across up to workers goroutines and merging their partial counts
// into a single map.
//
// If workers <= 0, one worker per element is used. An empty input yields an
// empty (non-nil) map. Each goroutine tallies into its own local map and the
// partials are merged under a mutex, so shared state is data-race-free and the
// result equals a sequential tally.
func ParallelHistogram(nums []int, workers int) map[int]int {
	result := make(map[int]int)

	if len(nums) == 0 {
		return result
	}

	// Determine actual number of workers
	actualWorkers := workers
	if actualWorkers <= 0 {
		actualWorkers = len(nums)
	}
	if actualWorkers > len(nums) {
		actualWorkers = len(nums)
	}

	// Calculate chunk size
	chunkSize := len(nums) / actualWorkers
	if chunkSize == 0 {
		chunkSize = 1
	}

	var wg sync.WaitGroup
	var mu sync.Mutex

	for i := 0; i < actualWorkers; i++ {
		start := i * chunkSize
		end := start + chunkSize

		// Last worker takes any remaining elements
		if i == actualWorkers-1 {
			end = len(nums)
		}

		// Skip if start is beyond slice length
		if start >= len(nums) {
			break
		}

		wg.Add(1)
		go func(slice []int) {
			defer wg.Done()

			// Local map for this worker
			local := make(map[int]int)
			for _, num := range slice {
				local[num]++
			}

			// Merge into result under mutex
			mu.Lock()
			for k, v := range local {
				result[k] += v
			}
			mu.Unlock()
		}(nums[start:end])
	}

	wg.Wait()
	return result
}
